CREATE OR REPLACE FUNCTION pkg_tabela_basica.fn_polo_ins(p_str_polo character varying, OUT p_int_polo_id bigint, OUT p_resultado character varying)
 RETURNS record
 LANGUAGE plpgsql
 AS $function$
 	/*
 		Inclui polo (correcao: nao insere mais a coluna de ID — gerada por identity)
 		Autor original: Mauro Franca | Correcao: KingJr/PDCase
 		Data correcao: 20260711
 	*/
 DECLARE
 	v_msg		 character varying(500);
 BEGIN
 
     BEGIN
 
 		INSERT INTO public.tb_polo(
 			  str_polo
 			)
 		VALUES (p_str_polo
 			)
 		RETURNING int_polo_id
 		INTO p_int_polo_id;
 
 		p_resultado := pkg_sistema_util.fn_mensagem('GER-S001');
 
     EXCEPTION
 
         WHEN SQLSTATE 'P0001' THEN
 		    GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
 			p_int_polo_id := NULL;
             p_resultado := pkg_sistema_util.fn_mensagem('GER-E001', v_msg);
 
         WHEN OTHERS THEN
             p_int_polo_id := NULL;
             p_resultado := pkg_sistema_util.fn_mensagem('GER-E001', format('pkg_tabela_basica.fn_polo_ins - Mensagem de erro: %s (%s).', SQLERRM, SQLSTATE));
 
     END;
 END;
 $function$;

