-- ── Correção pkg_fato_ocorrido.fn_fato_ocorrido_del (removido delete de tb_consequencia_violencia) ──
CREATE OR REPLACE FUNCTION pkg_fato_ocorrido.fn_fato_ocorrido_del(p_int_fato_ocorrido_id bigint, OUT p_resultado character varying)
 RETURNS character varying
 LANGUAGE plpgsql
 AS $function$
 	/*
 		Exclui Fato Ocorrido (corrigido: removido delete de tb_consequencia_violencia que não possui coluna int_fato_ocorrido_id)
 		Autor original: Mauro França | Correções: Antonio Júnior
 		Data: 20260712
 	*/
 DECLARE 
 	v_msg		  		character varying(500);
 BEGIN
     BEGIN
 		delete 
 			from public.tb_fato_ocorrido_comunicante
 		where int_fato_ocorrido_id = p_int_fato_ocorrido_id;
 
 		delete 
 			from public.tb_medida_protetiva_urgencia
 		where int_mpu_id in (Select int_mpu_id 
 		                       from public.tb_fato_ocorrido_mpu
 		                       where int_fato_ocorrido_id = p_int_fato_ocorrido_id);
 		
 		delete 
 			from public.tb_fato_ocorrido_mpu
 		where int_fato_ocorrido_id = p_int_fato_ocorrido_id;		
 
 	    DELETE 
 		  FROM public.tb_fato_ocorrido
 			WHERE int_fato_ocorrido_id = p_int_fato_ocorrido_id;
 	
         IF NOT FOUND THEN
             p_resultado := pkg_sistema_util.fn_mensagem('GER-E999','Registro não encontrado para exclusão.');
             RETURN;
         END IF;
 		
         p_resultado := pkg_sistema_util.fn_mensagem('GER-S003');
 
     EXCEPTION
 	    WHEN SQLSTATE 'P0099' THEN
 			p_resultado:= pkg_sistema_util.fn_mensagem('GER-E003', v_msg);
 			
         WHEN SQLSTATE 'P0001' THEN
 		    GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
             p_resultado := pkg_sistema_util.fn_mensagem('GER-E003', v_msg);
 			
         WHEN OTHERS THEN
             p_resultado := pkg_sistema_util.fn_mensagem('GER-E003', format('pkg_fato_ocorrido.fn_fato_ocorrido_del - Mensagem de erro: %s (%s).', SQLERRM, SQLSTATE));
 
     END;
 END;
 $function$;
